<?php
require_once __DIR__.'/inc/bootstrap.php'; require_login(); require_admin(); require_once __DIR__.'/config/database.php'; require_once __DIR__.'/inc/audit.php'; $pdo=db(); csrf_check();
if($_SERVER['REQUEST_METHOD']==='POST') { $action=$_POST['action']??''; try {
 if($action==='save') { $id=(int)($_POST['id']??0); $title=trim($_POST['title']??''); $category=trim($_POST['category']??'General'); $date=$_POST['event_date']??''; $location=trim($_POST['location']??''); $description=trim($_POST['description']??''); $status=($_POST['status']??'open')==='closed'?'closed':'open'; if($title===''||$date===''||$location===''||$description==='') throw new RuntimeException('Complete all required event fields.');
 $poster=null; if(!empty($_FILES['poster']['name'])) { if($_FILES['poster']['error']!==UPLOAD_ERR_OK) throw new RuntimeException('Poster upload failed.'); if($_FILES['poster']['size']>2*1024*1024) throw new RuntimeException('Poster must be 2 MB or smaller.'); $finfo=new finfo(FILEINFO_MIME_TYPE); $mime=$finfo->file($_FILES['poster']['tmp_name']); $allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']; if(!isset($allowed[$mime])) throw new RuntimeException('Poster must be JPG, PNG or WEBP.'); $poster=bin2hex(random_bytes(12)).'.'.$allowed[$mime]; $dir=__DIR__.'/uploads/events'; if(!is_dir($dir)) mkdir($dir,0755,true); if(!move_uploaded_file($_FILES['poster']['tmp_name'],$dir.'/'.$poster)) throw new RuntimeException('Could not save poster file.'); }
 if($id) { if($poster){$q=$pdo->prepare('UPDATE events SET title=?,category=?,event_date=?,location=?,description=?,status=?,poster=? WHERE id=?');$q->execute([$title,$category,$date,$location,$description,$status,$poster,$id]);} else {$q=$pdo->prepare('UPDATE events SET title=?,category=?,event_date=?,location=?,description=?,status=? WHERE id=?');$q->execute([$title,$category,$date,$location,$description,$status,$id]);} audit_log($pdo,'event.update','Updated event #'.$id); } else {$q=$pdo->prepare('INSERT INTO events(title,category,event_date,location,description,status,poster,created_by) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$title,$category,$date,$location,$description,$status,$poster,$_SESSION['user_id']]);audit_log($pdo,'event.create','Created event '.$title);} flash('Event saved successfully.');
 } elseif($action==='delete'){ $id=(int)($_POST['id']??0); $q=$pdo->prepare('SELECT poster FROM events WHERE id=?');$q->execute([$id]);$old=$q->fetch();$q=$pdo->prepare('DELETE FROM events WHERE id=?');$q->execute([$id]);if($old && $old['poster']){ $file=__DIR__.'/uploads/events/'.$old['poster'];if(is_file($file))unlink($file);} audit_log($pdo,'event.delete','Deleted event #'.$id);flash('Event deleted.'); }
 } catch(Throwable $e){flash($e instanceof PDOException?'Database error while saving event.':$e->getMessage(),'error');} header('Location: events.php');exit; }
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM events WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$events=$pdo->query('SELECT * FROM events ORDER BY event_date DESC,id DESC')->fetchAll();$pageTitle='Event management';require __DIR__.'/inc/header.php'; ?>
<div class="page-heading"><div><div class="eyebrow">PRACTICAL 12</div><h1>Event management</h1><p>Manage campus events and safely upload poster images.</p></div><span class="pill">ADMIN ONLY</span></div>
<section class="panel"><h2><?= $edit?'Edit event':'Add event' ?></h2><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Event title<input required name="title" value="<?=e($edit['title']??'')?>"></label><label>Category<input name="category" value="<?=e($edit['category']??'General')?>"></label><label>Date<input required type="date" name="event_date" value="<?=e($edit['event_date']??'')?>"></label><label>Location<input required name="location" value="<?=e($edit['location']??'')?>"></label><label>Status<select name="status"><option value="open" <?=($edit['status']??'open')==='open'?'selected':''?>>Open</option><option value="closed" <?=($edit['status']??'')==='closed'?'selected':''?>>Closed</option></select></label><label>Poster (JPG/PNG/WEBP, max 2 MB)<input type="file" name="poster" accept="image/jpeg,image/png,image/webp"></label><label class="full-field">Description<textarea required name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><div><button class="btn">Save event</button></div></form></section>
<section class="panel"><h2>Events</h2><div class="table-wrap"><table><thead><tr><th>Poster</th><th>Title</th><th>Date</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $ev): ?><tr><td><?php if($ev['poster']): ?><img src="uploads/events/<?=e($ev['poster'])?>" alt="Poster for <?=e($ev['title'])?>" style="width:64px;height:48px;object-fit:cover;border-radius:8px"><?php else: ?>—<?php endif; ?></td><td><?=e($ev['title'])?><small><?=e($ev['category'])?></small></td><td><?=e($ev['event_date'])?></td><td><?=e($ev['location'])?></td><td><?=e($ev['status'])?></td><td><a href="?edit=<?=(int)$ev['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete this event?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$ev['id']?>"><button class="link-button">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="6">No events yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require __DIR__.'/inc/footer.php'; ?>
